CREATE TABLE loan_balance_publications (
 id TEXT PRIMARY KEY NOT NULL, loan_id TEXT NOT NULL REFERENCES loans(id), member_id TEXT NOT NULL REFERENCES members(id),
 member_name TEXT NOT NULL, member_number TEXT NOT NULL, link_id TEXT NOT NULL REFERENCES member_user_links(id), user_id TEXT NOT NULL REFERENCES "user"(id), user_name TEXT NOT NULL, user_email TEXT NOT NULL,
 currency TEXT NOT NULL, disbursement_date TEXT NOT NULL, principal_minor TEXT NOT NULL,
 observed_date TEXT NOT NULL, amount_minor TEXT NOT NULL, basis TEXT NOT NULL, source TEXT NOT NULL,
 published_by TEXT NOT NULL REFERENCES "user"(id), published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, publish_key TEXT NOT NULL UNIQUE,
 withdrawn_by TEXT REFERENCES "user"(id), withdrawn_at TEXT, withdraw_key TEXT UNIQUE,
 CHECK((withdrawn_by IS NULL AND withdrawn_at IS NULL AND withdraw_key IS NULL) OR (withdrawn_by IS NOT NULL AND withdrawn_at IS NOT NULL AND withdraw_key IS NOT NULL))
);
CREATE TRIGGER loan_balance_publish_guard BEFORE INSERT ON loan_balance_publications BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.published_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN NEW.observed_date<NEW.disbursement_date OR NEW.observed_date>date('now','+3 hours') OR date(NEW.observed_date,'+0 days') IS NOT NEW.observed_date OR length(NEW.amount_minor) NOT BETWEEN 1 AND 30 OR NEW.amount_minor GLOB '*[^0-9]*' OR (length(NEW.amount_minor)>1 AND substr(NEW.amount_minor,1,1)='0') OR length(trim(NEW.basis)) NOT BETWEEN 1 AND 500 OR length(trim(NEW.source)) NOT BETWEEN 1 AND 500 THEN RAISE(ABORT,'invalid balance') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loans l JOIN members m ON m.id=l.member_id AND m.status='active' JOIN member_user_links k ON k.member_id=m.id AND k.revoked_at IS NULL JOIN "user" u ON u.id=k.user_id WHERE l.id=NEW.loan_id AND l.member_id=NEW.member_id AND m.full_name=NEW.member_name AND m.member_number=NEW.member_number AND k.id=NEW.link_id AND u.id=NEW.user_id AND u.name=NEW.user_name AND u.email=NEW.user_email AND l.currency=NEW.currency AND l.disbursement_date=NEW.disbursement_date AND CAST(l.principal_minor AS TEXT)=NEW.principal_minor AND NOT EXISTS(SELECT 1 FROM loan_source_voids x WHERE x.source_kind='loan' AND x.source_id=l.id)) THEN RAISE(ABORT,'loan or recipient changed') END;
END;
CREATE TRIGGER loan_balance_immutable BEFORE UPDATE ON loan_balance_publications WHEN NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.member_id IS NOT OLD.member_id OR NEW.member_name IS NOT OLD.member_name OR NEW.member_number IS NOT OLD.member_number OR NEW.link_id IS NOT OLD.link_id OR NEW.user_id IS NOT OLD.user_id OR NEW.user_name IS NOT OLD.user_name OR NEW.user_email IS NOT OLD.user_email OR NEW.currency IS NOT OLD.currency OR NEW.disbursement_date IS NOT OLD.disbursement_date OR NEW.principal_minor IS NOT OLD.principal_minor OR NEW.observed_date IS NOT OLD.observed_date OR NEW.amount_minor IS NOT OLD.amount_minor OR NEW.basis IS NOT OLD.basis OR NEW.source IS NOT OLD.source OR NEW.published_by IS NOT OLD.published_by OR NEW.published_at IS NOT OLD.published_at OR NEW.publish_key IS NOT OLD.publish_key OR OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL OR NEW.withdrawn_by IS NULL OR NEW.withdraw_key IS NULL OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.withdrawn_by AND role='admin') BEGIN SELECT RAISE(ABORT,'balance publication immutable'); END;
CREATE TRIGGER loan_balance_no_delete BEFORE DELETE ON loan_balance_publications BEGIN SELECT RAISE(ABORT,'balance publication immutable'); END;
CREATE TRIGGER loan_balance_source_no_change BEFORE UPDATE OF id,member_id,currency,disbursement_date,principal_minor ON loans WHEN EXISTS(SELECT 1 FROM loan_balance_publications p WHERE p.loan_id=OLD.id) AND (NEW.id IS NOT OLD.id OR NEW.member_id IS NOT OLD.member_id OR NEW.currency IS NOT OLD.currency OR NEW.disbursement_date IS NOT OLD.disbursement_date OR NEW.principal_minor IS NOT OLD.principal_minor) BEGIN SELECT RAISE(ABORT,'reported loan source immutable'); END;
CREATE TRIGGER loan_balance_source_no_delete BEFORE DELETE ON loans WHEN EXISTS(SELECT 1 FROM loan_balance_publications p WHERE p.loan_id=OLD.id) BEGIN SELECT RAISE(ABORT,'reported loan source immutable'); END;
